def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    own = []
    opp = []
    opp_D = 0
    opp_C = 0
    bad = 0

    for i in range(n):
        o, p = history[i]
        own.append(o)
        opp.append(p)

        if p == 'D':
            opp_D += 1
            if i == 0 or own[i - 1] == 'C':
                bad += 1
        else:
            opp_C += 1

    if opp_D == 0:
        return 'D' if n >= 8 else 'C'

    if opp_C == 0:
        return 'D'

    d_streak = 0
    for i in range(n - 1, -1, -1):
        if opp[i] == 'D':
            d_streak += 1
        else:
            break

    start = 0
    if n >= 10:
        start = n - 10

    recent_D = 0
    recent_bad = 0
    for i in range(start, n):
        if opp[i] == 'D':
            recent_D += 1
            if i == 0 or own[i - 1] == 'C':
                recent_bad += 1

    last_opp = opp[-1]
    last_own = own[-1]

    if bad == 0:
        return 'C'

    if last_opp == 'D':
        if recent_bad >= 2 or d_streak >= 3 or bad >= 5 or recent_D >= 5 or opp_D * 2 > n:
            return 'D'

        if opp_C * 4 > n * 3:
            if last_own == 'C' and bad <= 2 and recent_bad <= 1 and d_streak <= 2:
                return 'D'
            if last_own == 'D' and bad <= 3 and d_streak <= 2 and recent_D <= 2:
                return 'C'
            return 'D' if rng.random() < 0.55 else 'C'

        if last_own == 'D' and bad <= 2 and d_streak <= 2:
            return 'C'
        return 'D'

    if recent_D >= 4 or bad >= 5 or opp_D * 2 > n:
        return 'D'

    if opp_C * 10 > n * 9 and rng.random() < 0.01:
        return 'D'

    return 'C'
